  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : float
  + OptionsAndCustomizations : string
  + DeliveryDate : date
}

class Airplane {
}

Boeing "1" -- "*" Contract : manages
Boeing "1" -- "*" Airplane : builds
Contract "1" *-- "1..*" Acquisition : consists of
Acquisition "1" -- "1" Airplane : results in
Contract "*" -- "1" Employee : is managed by
Contract "*" -- "0..1" Employee : is assigned to
Airline "0..1" -- "0..*" Airline : mother-daughter relationship
Airline "1" -- "0..*" Contract : signs
Acquisition "0..*" -- "1" Airline : belongs to

@enduml

